"""
_offlinai_binwalk.py — pure-Python firmware analysis & extraction, in the
spirit of binwalk, focused on Android images. No third-party dependencies:
uses stdlib zlib / lzma / bz2 plus hand-rolled parsers for the formats those
don't cover.

What it does
------------
* scan(path)            — binwalk-style signature scan (offsets + descriptions)
* extract(path, outdir) — carve & decompress known streams, recursively
* Android sparse image  → raw            (simg2img)
* Android boot / vendor_boot image       → kernel + ramdisk(+dtb), then recurse
* ext4 filesystem       → files          (extent-based; modern Android images)
* LZ4 frame / legacy + gzip / xz / bzip2 / lzma / zlib / cpio / tar / zip

The Android payload chain is usually:  super.img (sparse) → raw → ext4 → files,
or  boot.img → ramdisk (lz4/gzip cpio) → init files.  This walks that chain.

Everything streams from disk (seek/read, mmap for scanning) so multi-GB
system images don't have to fit in RAM.
"""

import os
import io
import struct
import zlib
import lzma
import bz2
import mmap

__all__ = [
    "scan", "extract", "sparse_to_raw", "is_sparse", "is_ext4", "is_bootimg",
    "unpack_bootimg", "Ext4", "lz4_decompress", "BinwalkError",
]


class BinwalkError(Exception):
    pass


# --------------------------------------------------------------------------
# Signature table — (magic, name, description, adjust)
# `adjust` is subtracted from the match offset to get the structure start
# (e.g. the ext4 superblock magic sits 0x438 bytes into the filesystem).
# --------------------------------------------------------------------------
_SIGS = [
    (b"\x1f\x8b\x08",                 "gzip",        "gzip compressed data", 0),
    (b"BZh",                          "bzip2",       "bzip2 compressed data", 0),
    (b"\xfd7zXZ\x00",                 "xz",          "XZ compressed data", 0),
    (b"\x5d\x00\x00\x80",             "lzma",        "LZMA compressed data (alone)", 0),
    (b"\x5d\x00\x00\x10",             "lzma",        "LZMA compressed data (alone)", 0),
    (b"\x04\x22\x4d\x18",             "lz4",         "LZ4 frame compressed data", 0),
    (b"\x02\x21\x4c\x18",             "lz4_legacy",  "LZ4 legacy compressed data", 0),
    (b"7z\xbc\xaf\x27\x1c",           "7z",          "7-zip archive data", 0),
    (b"PK\x03\x04",                   "zip",         "Zip archive data", 0),
    (b"\x89PNG\r\n\x1a\n",            "png",         "PNG image", 0),
    (b"\xff\xd8\xff",                 "jpeg",        "JPEG image", 0),
    (b"070701",                       "cpio",        "ASCII cpio archive (SVR4 newc)", 0),
    (b"070702",                       "cpio",        "ASCII cpio archive (SVR4 newc, crc)", 0),
    (b"hsqs",                         "squashfs",    "Squashfs filesystem (little-endian)", 0),
    (b"sqsh",                         "squashfs",    "Squashfs filesystem (big-endian)", 0),
    (b"\x45\x3d\xcd\x28",             "cramfs",      "CramFS filesystem", 0),
    (b"UBI#",                         "ubi",         "UBI erase-block", 0),
    (b"UBI!",                         "ubifs",       "UBIFS superblock", 0),
    (b"\x85\x19",                     "jffs2",       "JFFS2 filesystem (little-endian)", 0),
    (b"\x19\x85",                     "jffs2",       "JFFS2 filesystem (big-endian)", 0),
    (b"-rom1fs-",                     "romfs",       "RomFS filesystem", 0),
    (b"\xd0\x0d\xfe\xed",             "dtb",         "Device Tree Blob (DTB/FDT)", 0),
    (b"\x27\x05\x19\x56",             "uimage",      "u-boot legacy uImage", 0),
    (b"\x7fELF",                      "elf",         "ELF binary", 0),
    (b"ANDROID!",                     "bootimg",     "Android bootable image", 0),
    (b"VNDRBOOT",                     "vendor_boot", "Android vendor_boot image", 0),
    (b"\x3a\xff\x26\xed",             "sparse",      "Android sparse image", 0),
    (b"CrAU",                         "payload",     "Android A/B OTA payload (payload.bin)", 0),
    (b"AVB0",                         "vbmeta",      "Android Verified Boot (vbmeta)", 0),
    (b"AVBf",                         "avb_footer",  "Android Verified Boot footer", 0),
    (b"BOOTLDR!",                     "bootldr",     "Android bootloader image", 0),
    (b"\x53\xef",                     "ext",         "Linux ext2/3/4 filesystem", 0x438),
    (b"ustar",                        "tar",         "POSIX tar archive", 257),
]


def _describe_extra(fh, off, name):
    """Best-effort extra detail for a finding (size, version, label…)."""
    try:
        if name == "sparse":
            fh.seek(off)
            hdr = fh.read(28)
            (_m, _maj, _min, _fhsz, _chsz, blk, total_blks, total_chunks, _crc) = \
                struct.unpack("<IHHHHIIII", hdr)
            return f"blocks={total_blks} block_size={blk} chunks={total_chunks} (raw≈{total_blks*blk} bytes)"
        if name == "bootimg":
            fh.seek(off)
            hdr = fh.read(48)
            ver = struct.unpack_from("<I", hdr, 40)[0]
            return f"header v{ver}"
        if name == "ext":
            fh.seek(off - 0x438)
            sb = fh.read(0x438 + 0x100)
            if len(sb) >= 0x438 + 0x60:
                lbs = struct.unpack_from("<I", sb, 1024 + 24)[0]
                bcount = struct.unpack_from("<I", sb, 1024 + 4)[0]
                bs = 1024 << lbs
                incompat = struct.unpack_from("<I", sb, 1024 + 96)[0]
                kind = "ext4" if (incompat & 0x40) else "ext2/3"
                label = sb[1024 + 120:1024 + 136].split(b"\x00")[0].decode("latin1", "replace")
                lbl = f" label='{label}'" if label else ""
                return f"{kind} block_size={bs} size≈{bcount*bs} bytes{lbl}"
        if name == "gzip":
            fh.seek(off)
            head = fh.read(10)
            flg = head[3] if len(head) > 3 else 0
            fname = ""
            if flg & 0x08:  # FNAME
                fh.seek(off + 10)
                nm = b""
                while True:
                    c = fh.read(1)
                    if not c or c == b"\x00":
                        break
                    nm += c
                fname = f" name='{nm.decode('latin1','replace')}'"
            return f"original{fname}" if fname else ""
    except Exception:
        return ""
    return ""


def scan(path):
    """binwalk-style signature scan. Returns a list of dicts:
    {offset, name, description}.  Sorted by offset."""
    findings = []
    size = os.path.getsize(path)
    with open(path, "rb") as fh:
        mm = mmap.mmap(fh.fileno(), 0, access=mmap.ACCESS_READ) if size else b""
        try:
            for magic, name, desc, adjust in _SIGS:
                start = 0
                while True:
                    i = mm.find(magic, start) if size else -1
                    if i < 0:
                        break
                    off = i - adjust
                    if off >= 0:
                        # ext signature is only valid at a 1024-aligned fs start
                        if name == "ext" and (off % 1024) != 0:
                            pass
                        else:
                            extra = _describe_extra(fh, off, name)
                            findings.append({
                                "offset": off,
                                "name": name,
                                "description": desc + (f"  [{extra}]" if extra else ""),
                            })
                    start = i + 1
        finally:
            if size:
                mm.close()
    findings.sort(key=lambda d: (d["offset"], d["name"]))
    return findings


# --------------------------------------------------------------------------
# LZ4
# --------------------------------------------------------------------------
def _lz4_block(src, hint=None):
    """Decompress one raw LZ4 block (sequence of token/literal/match)."""
    out = bytearray()
    i, n = 0, len(src)
    while i < n:
        token = src[i]; i += 1
        lit = token >> 4
        if lit == 15:
            while True:
                b = src[i]; i += 1
                lit += b
                if b != 0xFF:
                    break
        out += src[i:i + lit]; i += lit
        if i >= n:
            break  # last sequence: literals only, no match
        offset = src[i] | (src[i + 1] << 8); i += 2
        if offset == 0:
            raise BinwalkError("LZ4: zero match offset")
        mlen = token & 0x0F
        if mlen == 15:
            while True:
                b = src[i]; i += 1
                mlen += b
                if b != 0xFF:
                    break
        mlen += 4
        start = len(out) - offset
        if start < 0:
            raise BinwalkError("LZ4: match before start")
        for _ in range(mlen):
            out.append(out[start]); start += 1
    return bytes(out)


def lz4_decompress(data, off=0):
    """Decompress an LZ4 *frame* (0x184D2204) or *legacy* (0x184C2102) stream
    starting at `off`. Returns (decompressed_bytes, end_offset)."""
    magic = data[off:off + 4]
    if magic == b"\x04\x22\x4d\x18":          # frame format
        p = off + 4
        flg, bd = data[p], data[p + 1]; p += 2
        if (flg >> 6) & 3 != 1:
            raise BinwalkError("LZ4: unsupported frame version")
        content_size = (flg >> 3) & 1
        content_checksum = (flg >> 2) & 1
        dict_id = flg & 1
        block_checksum = (flg >> 4) & 1
        if content_size:
            p += 8
        if dict_id:
            p += 4
        p += 1                                 # header checksum (HC)
        out = bytearray()
        while True:
            (bsize,) = struct.unpack_from("<I", data, p); p += 4
            if bsize == 0:                     # EndMark
                break
            uncompressed = bsize & 0x80000000
            bs = bsize & 0x7FFFFFFF
            block = data[p:p + bs]; p += bs
            out += block if uncompressed else _lz4_block(block)
            if block_checksum:
                p += 4
        if content_checksum:
            p += 4
        return bytes(out), p
    elif magic == b"\x02\x21\x4c\x18":         # legacy format
        p = off + 4
        out = bytearray()
        n = len(data)
        while p + 4 <= n:
            (bs,) = struct.unpack_from("<I", data, p)
            if bs == 0 or bs > 0x7E000000 or p + 4 + bs > n:
                break
            p += 4
            block = data[p:p + bs]; p += bs
            try:
                out += _lz4_block(block)
            except Exception:
                break
        return bytes(out), p
    raise BinwalkError("LZ4: not an LZ4 stream")


# --------------------------------------------------------------------------
# Android sparse image  → raw
# --------------------------------------------------------------------------
SPARSE_MAGIC = 0xED26FF3A
_CHUNK_RAW, _CHUNK_FILL, _CHUNK_DONTCARE, _CHUNK_CRC = 0xCAC1, 0xCAC2, 0xCAC3, 0xCAC4


def is_sparse(path):
    with open(path, "rb") as fh:
        return struct.unpack("<I", fh.read(4) or b"\x00\x00\x00\x00")[0] == SPARSE_MAGIC


def sparse_to_raw(src_path, dst_path, progress=None):
    """Convert an Android sparse image to a raw image (the `simg2img` job)."""
    with open(src_path, "rb") as fin, open(dst_path, "wb") as fout:
        hdr = fin.read(28)
        (magic, major, minor, file_hdr_sz, chunk_hdr_sz, blk_sz,
         total_blks, total_chunks, _crc) = struct.unpack("<IHHHHIIII", hdr)
        if magic != SPARSE_MAGIC:
            raise BinwalkError("not an Android sparse image")
        if file_hdr_sz > 28:
            fin.seek(file_hdr_sz - 28, io.SEEK_CUR)
        written_blks = 0
        for _ in range(total_chunks):
            ch = fin.read(chunk_hdr_sz)
            if len(ch) < 12:
                break
            ctype, _res, chunk_sz, total_sz = struct.unpack_from("<HHII", ch, 0)
            if chunk_hdr_sz > 12:
                fin.seek(chunk_hdr_sz - 12, io.SEEK_CUR)
            data_sz = total_sz - chunk_hdr_sz
            out_bytes = chunk_sz * blk_sz
            if ctype == _CHUNK_RAW:
                remaining = data_sz
                while remaining > 0:
                    buf = fin.read(min(1 << 20, remaining))
                    if not buf:
                        break
                    fout.write(buf)
                    remaining -= len(buf)
            elif ctype == _CHUNK_FILL:
                fill = fin.read(4)
                fout.write(fill * (out_bytes // 4))
            elif ctype == _CHUNK_DONTCARE:
                fout.write(b"\x00" * out_bytes)
            elif ctype == _CHUNK_CRC:
                fin.read(4)
            else:
                raise BinwalkError(f"sparse: unknown chunk type 0x{ctype:x}")
            written_blks += chunk_sz
            if progress:
                progress(written_blks, total_blks)
        return written_blks * blk_sz


# --------------------------------------------------------------------------
# Android boot.img / vendor_boot
# --------------------------------------------------------------------------
def is_bootimg(path):
    with open(path, "rb") as fh:
        m = fh.read(8)
        return m == b"ANDROID!" or m == b"VNDRBOOT"


def _pad(n, page):
    return ((n + page - 1) // page) * page


def unpack_bootimg(path, outdir, log=None):
    """Split an Android boot.img / vendor_boot into its parts. Returns the list
    of files written. Handles header versions 0–4."""
    os.makedirs(outdir, exist_ok=True)
    written = []

    def emit(name, data):
        if not data:
            return
        p = os.path.join(outdir, name)
        with open(p, "wb") as f:
            f.write(data)
        written.append(p)
        if log:
            log(f"  {name}  ({len(data)} bytes)")

    with open(path, "rb") as fh:
        magic = fh.read(8)
        fh.seek(0)
        blob = fh.read()

    if magic == b"ANDROID!":
        ver = struct.unpack_from("<I", blob, 40)[0]
        if ver < 3:
            (ksize, _ka, rsize, _ra, ssize, _sa, _tags, page) = \
                struct.unpack_from("<IIIIIIII", blob, 8)
            n = page
            koff = n
            roff = koff + _pad(ksize, page)
            soff = roff + _pad(rsize, page)
            emit("kernel", blob[koff:koff + ksize])
            emit("ramdisk", blob[roff:roff + rsize])
            if ssize:
                emit("second", blob[soff:soff + ssize])
        else:  # v3 / v4 — fixed 4096 page, no per-section addresses
            page = 4096
            ksize, rsize = struct.unpack_from("<II", blob, 8)
            koff = page
            roff = koff + _pad(ksize, page)
            emit("kernel", blob[koff:koff + ksize])
            emit("ramdisk", blob[roff:roff + rsize])
    elif magic == b"VNDRBOOT":
        (ver, page) = struct.unpack_from("<II", blob, 8)
        # header_version@8, page_size@12, kernel_addr@16, ramdisk_addr@20,
        # vendor_ramdisk_size@24, cmdline[2048]@28, tags@2076, name[16]@2080,
        # header_size@2096, dtb_size@2100
        vrsize = struct.unpack_from("<I", blob, 24)[0]
        hdr_size = struct.unpack_from("<I", blob, 2096)[0]
        dtb_size = struct.unpack_from("<I", blob, 2100)[0]
        o = _pad(hdr_size, page)
        emit("vendor_ramdisk", blob[o:o + vrsize])
        o += _pad(vrsize, page)
        if dtb_size:
            emit("dtb", blob[o:o + dtb_size])
    else:
        raise BinwalkError("not a boot image")
    return written


# --------------------------------------------------------------------------
# ext4 (extent-based — modern Android images)
# --------------------------------------------------------------------------
class _Inode:
    __slots__ = ("mode", "size", "flags", "block", "ino")


class Ext4:
    """Minimal read-only ext4 reader: extents, directories, regular files and
    fast symlinks. Enough to unpack an Android system/vendor/product image."""

    S_IFMT = 0xF000
    S_IFREG = 0x8000
    S_IFDIR = 0x4000
    S_IFLNK = 0xA000

    def __init__(self, path):
        self.f = open(path, "rb")
        self.skipped = []          # names we couldn't extract (visible, not silent)
        self._read_super()

    def close(self):
        try:
            self.f.close()
        except Exception:
            pass

    def _u(self, off, n):
        self.f.seek(off)
        return int.from_bytes(self.f.read(n), "little")

    def _read_super(self):
        self.f.seek(1024)
        sb = self.f.read(1024)
        if struct.unpack_from("<H", sb, 56)[0] != 0xEF53:
            raise BinwalkError("not an ext filesystem (bad superblock magic)")
        self.inodes_count = struct.unpack_from("<I", sb, 0)[0]
        log_bs = struct.unpack_from("<I", sb, 24)[0]
        self.block_size = 1024 << log_bs
        self.blocks_per_group = struct.unpack_from("<I", sb, 32)[0]
        self.inodes_per_group = struct.unpack_from("<I", sb, 40)[0]
        rev = struct.unpack_from("<I", sb, 76)[0]
        self.inode_size = struct.unpack_from("<H", sb, 88)[0] if rev >= 1 else 128
        self.feature_incompat = struct.unpack_from("<I", sb, 96)[0]
        self.is64 = bool(self.feature_incompat & 0x80)
        self.desc_size = struct.unpack_from("<H", sb, 254)[0] if self.is64 else 32
        if self.desc_size < 32:
            self.desc_size = 32
        # group descriptors start at the block right after the superblock
        self.gd_block = 1 if self.block_size > 1024 else 2

    def _group_desc_inode_table(self, group):
        off = self.gd_block * self.block_size + group * self.desc_size
        lo = self._u(off + 8, 4)
        hi = self._u(off + 40, 4) if (self.is64 and self.desc_size >= 64) else 0
        return lo | (hi << 32)

    def _read_inode(self, ino):
        group = (ino - 1) // self.inodes_per_group
        index = (ino - 1) % self.inodes_per_group
        table = self._group_desc_inode_table(group)
        off = table * self.block_size + index * self.inode_size
        self.f.seek(off)
        raw = self.f.read(self.inode_size)
        n = _Inode()
        n.ino = ino
        n.mode = struct.unpack_from("<H", raw, 0)[0]
        size_lo = struct.unpack_from("<I", raw, 4)[0]
        size_hi = struct.unpack_from("<I", raw, 108)[0]
        n.size = size_lo | (size_hi << 32)
        n.flags = struct.unpack_from("<I", raw, 32)[0]
        n.block = raw[40:40 + 60]
        return n

    def _extents(self, block_bytes):
        """Yield (logical_block, physical_block, length) from an extent tree."""
        if struct.unpack_from("<H", block_bytes, 0)[0] != 0xF30A:
            return
        entries = struct.unpack_from("<H", block_bytes, 2)[0]
        depth = struct.unpack_from("<H", block_bytes, 6)[0]
        if depth == 0:
            for i in range(entries):
                o = 12 + i * 12
                ee_block = struct.unpack_from("<I", block_bytes, o)[0]
                ee_len = struct.unpack_from("<H", block_bytes, o + 4)[0]
                ee_start_hi = struct.unpack_from("<H", block_bytes, o + 6)[0]
                ee_start_lo = struct.unpack_from("<I", block_bytes, o + 8)[0]
                if ee_len > 32768:
                    ee_len -= 32768            # uninitialized extent
                phys = ee_start_lo | (ee_start_hi << 32)
                yield (ee_block, phys, ee_len)
        else:
            for i in range(entries):
                o = 12 + i * 12
                ei_leaf_lo = struct.unpack_from("<I", block_bytes, o + 4)[0]
                ei_leaf_hi = struct.unpack_from("<H", block_bytes, o + 8)[0]
                leaf = ei_leaf_lo | (ei_leaf_hi << 32)
                self.f.seek(leaf * self.block_size)
                child = self.f.read(self.block_size)
                yield from self._extents(child)

    def _read_inode_data(self, inode):
        """Full contents of any inode — handles inline data (modern ext4),
        extent trees (ext4) AND the classic indirect block map (ext2/3), so
        it works across filesystem variants, not just Android extent images."""
        if inode.flags & 0x10000000:             # EXT4_INLINE_DATA_FL
            return bytes(inode.block[:min(inode.size, 60)])
        out = bytearray(inode.size)
        if inode.flags & 0x80000:                # EXT4_EXTENTS_FL
            for logical, phys, length in self._extents(inode.block):
                for j in range(length):
                    pos = (logical + j) * self.block_size
                    if pos >= inode.size:
                        continue
                    self.f.seek((phys + j) * self.block_size)
                    data = self.f.read(self.block_size)
                    end = min(pos + self.block_size, inode.size)
                    out[pos:end] = data[:end - pos]
        else:                                    # ext2/3 indirect block map
            for idx, b in enumerate(self._blockmap(inode)):
                pos = idx * self.block_size
                if pos >= inode.size:
                    break
                if b == 0:
                    continue                      # sparse hole → leave zeros
                self.f.seek(b * self.block_size)
                data = self.f.read(self.block_size)
                end = min(pos + self.block_size, inode.size)
                out[pos:end] = data[:end - pos]
        return bytes(out)

    def _blockmap(self, inode):
        """Ordered data-block numbers for an ext2/3 (non-extent) inode:
        12 direct + single/double/triple indirect."""
        ptrs = struct.unpack_from("<15I", inode.block, 0)
        ppb = self.block_size // 4
        blocks = list(ptrs[0:12])
        for lvl, p in ((1, ptrs[12]), (2, ptrs[13]), (3, ptrs[14])):
            if p:
                blocks.extend(self._indirect(p, lvl, ppb))
        return blocks

    def _indirect(self, block, level, ppb):
        self.f.seek(block * self.block_size)
        ptrs = struct.unpack_from("<%dI" % ppb, self.f.read(self.block_size))
        if level == 1:
            return list(ptrs)
        out = []
        for p in ptrs:
            if not p:
                break
            out.extend(self._indirect(p, level - 1, ppb))
        return out

    def read_file(self, inode):
        """Return the full contents of a regular-file inode."""
        return self._read_inode_data(inode)

    def _read_dir_blocks(self, inode):
        return self._read_inode_data(inode)

    def _iter_dir(self, inode):
        data = self._read_dir_blocks(inode)
        off = 0
        n = len(data)
        while off + 8 <= n:
            ino = struct.unpack_from("<I", data, off)[0]
            rec_len = struct.unpack_from("<H", data, off + 4)[0]
            name_len = data[off + 6]
            file_type = data[off + 7]
            if rec_len < 8:
                break
            if ino != 0 and name_len:
                name = data[off + 8:off + 8 + name_len].decode("utf-8", "replace")
                if name not in (".", ".."):
                    yield (name, ino, file_type)
            off += rec_len

    def extract_all(self, outdir, log=None, _ino=2, _rel=""):
        """Recursively extract everything under inode `_ino` (root=2)."""
        os.makedirs(outdir, exist_ok=True)
        count = 0
        node = self._read_inode(_ino)
        for name, ino, ftype in self._iter_dir(node):
            safe = name.replace("/", "_")
            rel = os.path.join(_rel, safe)
            child = self._read_inode(ino)
            mode = child.mode & self.S_IFMT
            dest = os.path.join(outdir, safe)
            if mode == self.S_IFDIR:
                count += self.extract_all(dest, log, ino, rel)
            elif mode == self.S_IFREG:
                try:
                    with open(dest, "wb") as f:
                        f.write(self.read_file(child))
                    count += 1
                    if log:
                        log(f"  {rel}")
                except Exception as e:
                    self.skipped.append(rel)
                    if log:
                        log(f"  ! {rel}: {e}")
            elif mode == self.S_IFLNK:
                # fast symlink: target stored inline in i_block (< 60 bytes)
                try:
                    if child.size < 60 and not (child.flags & 0x80000):
                        target = child.block[:child.size].decode("utf-8", "replace")
                    else:
                        target = self.read_file(child).decode("utf-8", "replace")
                    try:
                        os.symlink(target, dest)
                    except (OSError, NotImplementedError):
                        with open(dest, "w") as f:
                            f.write(target)
                    count += 1
                except Exception:
                    pass
        return count


def is_ext4(path):
    try:
        with open(path, "rb") as fh:
            fh.seek(1024 + 56)
            return fh.read(2) == b"\x53\xef"
    except Exception:
        return False


# --------------------------------------------------------------------------
# Generic stream decompression (for carving)
# --------------------------------------------------------------------------
def _decompress_stream(data, off, name):
    """Decompress a single known stream beginning at `off`. Returns
    (bytes, consumed_end_offset) or raises."""
    if name == "gzip":
        d = zlib.decompressobj(16 + zlib.MAX_WBITS)
        out = d.decompress(data[off:])
        out += d.flush()
        return out, len(data) - len(d.unused_data)
    if name == "zlib":
        d = zlib.decompressobj()
        out = d.decompress(data[off:])
        out += d.flush()
        return out, len(data) - len(d.unused_data)
    if name == "xz":
        d = lzma.LZMADecompressor()
        out = d.decompress(data[off:])
        return out, (len(data) - len(d.unused_data)) if d.eof else len(data)
    if name == "lzma":
        d = lzma.LZMADecompressor(format=lzma.FORMAT_ALONE)
        out = d.decompress(data[off:])
        return out, (len(data) - len(d.unused_data)) if d.eof else len(data)
    if name == "bzip2":
        d = bz2.BZ2Decompressor()
        out = d.decompress(data[off:])
        return out, (len(data) - len(d.unused_data)) if d.eof else len(data)
    if name in ("lz4", "lz4_legacy"):
        return lz4_decompress(data, off)
    raise BinwalkError(f"no stream decompressor for {name}")


_CARVE_EXT = {
    "gzip": "gz", "zlib": "zlib", "xz": "xz", "lzma": "lzma", "bzip2": "bz2",
    "lz4": "lz4", "lz4_legacy": "lz4",
}


# --------------------------------------------------------------------------
# Top-level extract — the "just unpack my android img" entry point
# --------------------------------------------------------------------------
def extract(path, outdir=None, recursive=True, log=None, _depth=0, _maxdepth=8):
    """Auto-detect and extract. For a sparse/boot/ext4/payload image it does
    the right structural unpack; otherwise it signature-carves & decompresses
    embedded streams. Recurses into the results (matryoshka) up to _maxdepth.

    Returns the output directory."""
    log = log or (lambda *_: None)
    path = os.path.abspath(path)
    if outdir is None:
        outdir = path + ".extracted"
    os.makedirs(outdir, exist_ok=True)
    if _depth > _maxdepth:
        log(f"  (max recursion depth reached at {path})")
        return outdir

    # 1) Android sparse → raw, then recurse on the raw image
    if is_sparse(path):
        raw = os.path.join(outdir, os.path.basename(path) + ".raw")
        log(f"[sparse] {os.path.basename(path)} → raw")
        sparse_to_raw(path, raw)
        if recursive:
            extract(raw, raw + ".extracted", recursive, log, _depth + 1, _maxdepth)
        return outdir

    # 2) Android boot / vendor_boot → kernel + ramdisk, recurse on each
    if is_bootimg(path):
        log(f"[bootimg] {os.path.basename(path)}")
        parts = unpack_bootimg(path, outdir, log)
        if recursive:
            for p in parts:
                if os.path.basename(p) in ("ramdisk", "vendor_ramdisk", "kernel"):
                    extract(p, p + ".extracted", recursive, log, _depth + 1, _maxdepth)
        return outdir

    # 3) ext4 → files
    if is_ext4(path):
        log(f"[ext4] {os.path.basename(path)} → files")
        fs = Ext4(path)
        try:
            n = fs.extract_all(os.path.join(outdir, "root"), log)
            if fs.skipped:
                log(f"[ext4] extracted {n} entries, SKIPPED {len(fs.skipped)} "
                    f"(e.g. {', '.join(fs.skipped[:3])})")
            else:
                log(f"[ext4] extracted {n} entries")
        finally:
            fs.close()
        return outdir

    # 4) Whole-file single compressed stream? (gzip/xz/bz2/lz4/lzma ramdisk)
    with open(path, "rb") as fh:
        head = fh.read(8)
    single = None
    if head[:3] == b"\x1f\x8b\x08":
        single = "gzip"
    elif head[:6] == b"\xfd7zXZ\x00":
        single = "xz"
    elif head[:3] == b"BZh":
        single = "bzip2"
    elif head[:4] in (b"\x04\x22\x4d\x18", b"\x02\x21\x4c\x18"):
        single = "lz4"
    elif head[:4] in (b"\x5d\x00\x00\x80", b"\x5d\x00\x00\x10"):
        single = "lzma"
    if single:
        data = open(path, "rb").read()
        try:
            out, _end = _decompress_stream(data, 0, single)
            dest = os.path.join(outdir, os.path.basename(path) + ".out")
            with open(dest, "wb") as f:
                f.write(out)
            log(f"[{single}] {os.path.basename(path)} → {os.path.basename(dest)} ({len(out)} bytes)")
            # cpio ramdisk inside?
            if out[:6] in (b"070701", b"070702"):
                cdir = dest + ".cpio_root"
                cnt = _extract_cpio(out, cdir, log)
                log(f"[cpio] {cnt} entries")
            elif recursive:
                extract(dest, dest + ".extracted", recursive, log, _depth + 1, _maxdepth)
            return outdir
        except Exception as e:
            log(f"  ! {single} decompress failed: {e}")

    # 5) cpio?
    if head[:6] in (b"070701", b"070702"):
        data = open(path, "rb").read()
        cnt = _extract_cpio(data, os.path.join(outdir, "cpio_root"), log)
        log(f"[cpio] {cnt} entries")
        return outdir

    # 6) Fallback: signature-carve embedded compressed streams
    log(f"[carve] scanning {os.path.basename(path)} for embedded streams")
    data = open(path, "rb").read()
    found = scan(path)
    carved = 0
    for f in found:
        name = f["name"]
        if name not in _CARVE_EXT:
            continue
        off = f["offset"]
        try:
            out, _end = _decompress_stream(data, off, name)
            if len(out) < 8:
                continue
            dest = os.path.join(outdir, f"{off:#x}.{_CARVE_EXT[name]}.out")
            with open(dest, "wb") as fo:
                fo.write(out)
            carved += 1
            log(f"  carved {name} @ {off:#x} → {len(out)} bytes")
            if recursive and _depth + 1 <= _maxdepth:
                if out[:6] in (b"070701", b"070702"):
                    _extract_cpio(out, dest + ".cpio_root", log)
        except Exception:
            continue
    if carved == 0:
        log("  (no extractable embedded streams found)")
    return outdir


def _extract_cpio(data, outdir, log=None):
    """Extract a SVR4 'newc' cpio archive from `data`."""
    os.makedirs(outdir, exist_ok=True)
    p, n, count = 0, len(data), 0
    while p + 110 <= n:
        if data[p:p + 6] not in (b"070701", b"070702"):
            break

        def h(i):
            return int(data[p + 6 + i * 8:p + 6 + i * 8 + 8], 16)

        mode = h(1)
        filesize = h(6)
        namesize = h(11)
        name = data[p + 110:p + 110 + namesize - 1].decode("utf-8", "replace")
        name_field_end = p + 110 + namesize
        name_pad = (4 - (name_field_end % 4)) % 4
        data_start = name_field_end + name_pad
        if name == "TRAILER!!!":
            break
        file_data = data[data_start:data_start + filesize]
        data_pad = (4 - (filesize % 4)) % 4
        p = data_start + filesize + data_pad

        safe = name.replace("..", "__").lstrip("/")
        dest = os.path.join(outdir, safe)
        ftype = mode & 0o170000
        try:
            if ftype == 0o040000:               # directory
                os.makedirs(dest, exist_ok=True)
            elif ftype == 0o120000:             # symlink
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                target = file_data.decode("utf-8", "replace")
                try:
                    os.symlink(target, dest)
                except Exception:
                    with open(dest, "w") as f:
                        f.write(target)
                count += 1
            else:                               # regular / device → write data
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                with open(dest, "wb") as f:
                    f.write(file_data)
                count += 1
                if log:
                    log(f"  {safe}")
        except Exception:
            pass
    return count
